import React, { useState, useEffect } from 'react';

export function RecommendationWidget({ userId, maxItems = 5, onAddToCart }) {
  const [recommendations, setRecommendations] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    if (!userId) return;

    fetch(`http://localhost:5000/api/recommendations/${userId}?limit=${maxItems}`)
      .then(res => res.json())
      .then(data => {
        setRecommendations(data.recommendations || []);
        setLoading(false);
      })
      .catch(err => {
        console.error('Recommendation error:', err);
        setLoading(false);
      });
  }, [userId, maxItems]);

  if (loading) return <div>Loading recommendations...</div>;
  if (recommendations.length === 0) return null;

  const handleAddToCart = (product) => {
    if (typeof onAddToCart === 'function') {
      onAddToCart(product);
      return;
    }

    const cart = JSON.parse(localStorage.getItem('cart') || '[]');
    const existing = cart.find((item) => item._id === product._id);
    if (existing) {
      existing.quantity = (existing.quantity || 1) + 1;
    } else {
      cart.push({ ...product, quantity: 1 });
    }
    localStorage.setItem('cart', JSON.stringify(cart));
  };

  return (
    <div className="recommendation-widget">
      <h3>Recommended for You</h3>
      <div className="recommendation-list">
        {recommendations.map(product => (
          <div key={product._id} className="recommendation-item">
            <img src={product.imageUrl?.[0] || ''} alt={product.name} />
            <h4>{product.name}</h4>
            <p>${product.price}</p>
            <button onClick={() => handleAddToCart(product)}>Add to Cart</button>
          </div>
        ))}
      </div>
    </div>
  );
}

export default RecommendationWidget;
